static QString LText(LocalText id){
    using A=std::array<const char*,6>;static const A text[]={
        A{"I Have No Key Yet","Ich habe noch keinen Schlüssel","У меня пока нет ключа","У мене ще немає ключа","Je n’ai pas encore de clé","Aún no tengo una clave"},
        A{"API key status","Status des API-Schlüssels","Состояние ключа API","Стан ключа API","État de la clé API","Estado de la clave de API"},
        A{"A key is stored. Enter a new key and activate Save key to replace it.","Ein Schlüssel ist gespeichert. Geben Sie einen neuen Schlüssel ein und wählen Sie Schlüssel speichern, um ihn zu ersetzen.","Ключ сохранён. Чтобы заменить его, введите новый ключ и нажмите «Сохранить ключ».","Ключ збережено. Щоб замінити його, введіть новий ключ і натисніть «Зберегти ключ».","Une clé est enregistrée. Saisissez une nouvelle clé et activez Enregistrer la clé pour la remplacer.","Hay una clave guardada. Introduzca una clave nueva y active Guardar clave para reemplazarla."},
        A{"Enter a key and activate Save key. Closing this dialog discards unsaved text.","Geben Sie einen Schlüssel ein und wählen Sie Schlüssel speichern. Beim Schließen dieses Dialogs wird nicht gespeicherter Text verworfen.","Введите ключ и нажмите «Сохранить ключ». При закрытии диалога несохранённый текст будет удалён.","Введіть ключ і натисніть «Зберегти ключ». Після закриття діалогу незбережений текст буде видалено.","Saisissez une clé et activez Enregistrer la clé. La fermeture de cette boîte de dialogue supprime le texte non enregistré.","Introduzca una clave y active Guardar clave. Al cerrar este cuadro de diálogo se descarta el texto no guardado."},
        A{"OpenAI functions will remain unavailable until you save an API key. You can add one later from Tools > Accessible Studio > Video Tools > Manage OpenAI API Keys.","OpenAI-Funktionen bleiben nicht verfügbar, bis Sie einen API-Schlüssel speichern. Sie können ihn später unter Werkzeuge > Accessible Studio > Videowerkzeuge > OpenAI-API-Schlüssel verwalten hinzufügen.","Функции OpenAI будут недоступны, пока вы не сохраните ключ API. Его можно добавить позже через Сервис > Accessible Studio > Видеоинструменты > Управление ключами API OpenAI.","Функції OpenAI будуть недоступні, доки ви не збережете ключ API. Його можна додати пізніше через Сервіс > Accessible Studio > Відеоінструменти > Керування ключами API OpenAI.","Les fonctions OpenAI resteront indisponibles tant que vous n’aurez pas enregistré de clé API. Vous pourrez en ajouter une plus tard sous Outils > Accessible Studio > Outils vidéo > Gérer les clés API OpenAI.","Las funciones de OpenAI no estarán disponibles hasta que guarde una clave de API. Puede añadirla más adelante desde Herramientas > Accessible Studio > Herramientas de vídeo > Administrar claves de API de OpenAI."},
        A{"This function requires an OpenAI API key. Open Tools > Accessible Studio > Video Tools > Manage OpenAI API Keys to add one.","Diese Funktion benötigt einen OpenAI-API-Schlüssel. Öffnen Sie Werkzeuge > Accessible Studio > Videowerkzeuge > OpenAI-API-Schlüssel verwalten, um einen hinzuzufügen.","Для этой функции нужен ключ API OpenAI. Чтобы добавить его, откройте Сервис > Accessible Studio > Видеоинструменты > Управление ключами API OpenAI.","Для цієї функції потрібен ключ API OpenAI. Щоб додати його, відкрийте Сервіс > Accessible Studio > Відеоінструменти > Керування ключами API OpenAI.","Cette fonction nécessite une clé API OpenAI. Ouvrez Outils > Accessible Studio > Outils vidéo > Gérer les clés API OpenAI pour en ajouter une.","Esta función requiere una clave de API de OpenAI. Abra Herramientas > Accessible Studio > Herramientas de vídeo > Administrar claves de API de OpenAI para añadir una."},
        A{"Accessible Studio could not initialize or display the WebView2 content. Repair the Microsoft Edge WebView2 Runtime and try again.","Accessible Studio konnte den WebView2-Inhalt nicht initialisieren oder anzeigen. Reparieren Sie die Microsoft Edge WebView2 Runtime und versuchen Sie es erneut.","Accessible Studio не удалось инициализировать или отобразить содержимое WebView2. Восстановите среду выполнения Microsoft Edge WebView2 и повторите попытку.","Accessible Studio не вдалося ініціалізувати або відобразити вміст WebView2. Відновіть середовище виконання Microsoft Edge WebView2 і повторіть спробу.","Accessible Studio n’a pas pu initialiser ou afficher le contenu WebView2. Réparez le runtime Microsoft Edge WebView2 et réessayez.","Accessible Studio no pudo inicializar ni mostrar el contenido de WebView2. Repare Microsoft Edge WebView2 Runtime e inténtelo de nuevo."},
        A{"Accessible Studio could not create the Canvas Description window.","Accessible Studio konnte das Fenster für die Canvas-Beschreibung nicht erstellen.","Accessible Studio не удалось создать окно описания холста.","Accessible Studio не вдалося створити вікно опису полотна.","Accessible Studio n’a pas pu créer la fenêtre de description du canevas.","Accessible Studio no pudo crear la ventana de descripción del lienzo."},
        A{"Compatibility Analysis","Kompatibilitätsanalyse","Анализ совместимости","Аналіз сумісності","Analyse de compatibilité","Análisis de compatibilidad"},
        A{"Accessible Studio could not create the Compatibility Analysis window.","Accessible Studio konnte das Fenster für die Kompatibilitätsanalyse nicht erstellen.","Accessible Studio не удалось создать окно анализа совместимости.","Accessible Studio не вдалося створити вікно аналізу сумісності.","Accessible Studio n’a pas pu créer la fenêtre d’analyse de compatibilité.","Accessible Studio no pudo crear la ventana de análisis de compatibilidad."},
        A{"The compatibility report is available in this window, but it could not be copied to the Clipboard.","Der Kompatibilitätsbericht ist in diesem Fenster verfügbar, konnte aber nicht in die Zwischenablage kopiert werden.","Отчёт о совместимости доступен в этом окне, но его не удалось скопировать в буфер обмена.","Звіт про сумісність доступний у цьому вікні, але його не вдалося скопіювати до буфера обміну.","Le rapport de compatibilité est disponible dans cette fenêtre, mais il n’a pas pu être copié dans le Presse-papiers.","El informe de compatibilidad está disponible en esta ventana, pero no se pudo copiar al Portapapeles."},
        A{"Keyboard shortcut","Tastenkombination","Сочетание клавиш","Сполучення клавіш","Raccourci clavier","Método abreviado de teclado"},
        A{"Press the desired keyboard shortcut. Tab moves to the next control.","Drücken Sie die gewünschte Tastenkombination. Tab wechselt zum nächsten Steuerelement.","Нажмите нужное сочетание клавиш. Tab переходит к следующему элементу.","Натисніть потрібне сполучення клавіш. Tab переходить до наступного елемента.","Appuyez sur le raccourci clavier souhaité. Tab passe au contrôle suivant.","Pulse el método abreviado de teclado deseado. Tab pasa al control siguiente."},
        A{"That key cannot be assigned.","Diese Taste kann nicht zugewiesen werden.","Эту клавишу нельзя назначить.","Цю клавішу не можна призначити.","Cette touche ne peut pas être attribuée.","Esa tecla no se puede asignar."},
        A{"That keyboard shortcut is reserved for navigation or Windows and cannot be assigned here.","Diese Tastenkombination ist für die Navigation oder Windows reserviert und kann hier nicht zugewiesen werden.","Это сочетание зарезервировано для навигации или Windows и не может быть назначено здесь.","Це сполучення зарезервовано для навігації або Windows і не може бути призначено тут.","Ce raccourci clavier est réservé à la navigation ou à Windows et ne peut pas être attribué ici.","Ese método abreviado de teclado está reservado para la navegación o Windows y no se puede asignar aquí."},
        A{"OBS does not recognize that key.","OBS erkennt diese Taste nicht.","OBS не распознаёт эту клавишу.","OBS не розпізнає цю клавішу.","OBS ne reconnaît pas cette touche.","OBS no reconoce esa tecla."},
        A{"Choose Add Another Keyboard Shortcut or select an existing assignment before entering another keyboard shortcut.","Wählen Sie Weitere Tastenkombination hinzufügen oder eine vorhandene Zuweisung, bevor Sie eine weitere Tastenkombination eingeben.","Перед вводом другого сочетания выберите «Добавить ещё сочетание» или существующее назначение.","Перед введенням іншого сполучення виберіть «Додати ще одне сполучення» або наявне призначення.","Choisissez Ajouter un autre raccourci clavier ou sélectionnez une attribution existante avant de saisir un autre raccourci clavier.","Elija Añadir otro método abreviado de teclado o seleccione una asignación existente antes de introducir otro."},
        A{"That keyboard shortcut is already assigned to this command.","Diese Tastenkombination ist diesem Befehl bereits zugewiesen.","Это сочетание уже назначено этой команде.","Це сполучення вже призначено цій команді.","Ce raccourci clavier est déjà attribué à cette commande.","Ese método abreviado de teclado ya está asignado a este comando."},
        A{"%1 is already assigned to “%2”. Proceeding will remove that assignment and assign the keyboard shortcut to this command. Do you want to proceed anyway?","%1 ist bereits „%2“ zugewiesen. Wenn Sie fortfahren, wird diese Zuweisung entfernt und die Tastenkombination diesem Befehl zugewiesen. Möchten Sie trotzdem fortfahren?","%1 уже назначено команде «%2». Если продолжить, это назначение будет удалено, а сочетание назначено текущей команде. Всё равно продолжить?","%1 уже призначено команді «%2». Якщо продовжити, це призначення буде видалено, а сполучення призначено поточній команді. Усе одно продовжити?","%1 est déjà attribué à « %2 ». Si vous continuez, cette attribution sera supprimée et le raccourci clavier sera attribué à cette commande. Voulez-vous continuer quand même ?","%1 ya está asignado a «%2». Si continúa, se eliminará esa asignación y el método abreviado de teclado se asignará a este comando. ¿Desea continuar de todos modos?"},
        A{"Keyboard shortcut captured: %1.","Tastenkombination erfasst: %1.","Сочетание записано: %1.","Сполучення записано: %1.","Raccourci clavier capturé : %1.","Método abreviado de teclado capturado: %1."},
        A{"None","Keine","Нет","Немає","Aucun","Ninguno"},
        A{"Keyboard Shortcut","Tastenkombination","Сочетание клавиш","Сполучення клавіш","Raccourci clavier","Método abreviado de teclado"},
        A{"Command: %1","Befehl: %1","Команда: %1","Команда: %1","Commande : %1","Comando: %1"},
        A{"Assigned keyboard shortcuts","Zugewiesene Tastenkombinationen","Назначенные сочетания","Призначені сполучення","Raccourcis clavier attribués","Métodos abreviados de teclado asignados"},
        A{"Use the arrow keys to select an assignment. Tab moves to the Keyboard Shortcut field.","Wählen Sie mit den Pfeiltasten eine Zuweisung. Tab wechselt zum Feld Tastenkombination.","Выберите назначение стрелками. Tab переходит к полю сочетания клавиш.","Виберіть призначення стрілками. Tab переходить до поля сполучення клавіш.","Utilisez les flèches pour sélectionner une attribution. Tab passe au champ Raccourci clavier.","Use las flechas para seleccionar una asignación. Tab pasa al campo Método abreviado de teclado."},
        A{"&Keyboard shortcut:","&Tastenkombination:","&Сочетание клавиш:","&Сполучення клавіш:","&Raccourci clavier :","&Método abreviado de teclado:"},
        A{"Command: %1. Press the desired keyboard shortcut. Tab moves to the next control.","Befehl: %1. Drücken Sie die gewünschte Tastenkombination. Tab wechselt zum nächsten Steuerelement.","Команда: %1. Нажмите нужное сочетание клавиш. Tab переходит к следующему элементу.","Команда: %1. Натисніть потрібне сполучення клавіш. Tab переходить до наступного елемента.","Commande : %1. Appuyez sur le raccourci clavier souhaité. Tab passe au contrôle suivant.","Comando: %1. Pulse el método abreviado de teclado deseado. Tab pasa al control siguiente."},
        A{"&Add Another Keyboard Shortcut","&Weitere Tastenkombination hinzufügen","&Добавить ещё сочетание","&Додати ще одне сполучення","&Ajouter un autre raccourci clavier","&Añadir otro método abreviado de teclado"},
        A{"&Remove Keyboard Shortcut","Tastenkombination &entfernen","&Удалить сочетание","&Видалити сполучення","&Supprimer le raccourci clavier","&Eliminar método abreviado de teclado"},
        A{"Select an assigned keyboard shortcut before removing it.","Wählen Sie vor dem Entfernen eine zugewiesene Tastenkombination.","Перед удалением выберите назначенное сочетание.","Перед видаленням виберіть призначене сполучення.","Sélectionnez un raccourci clavier attribué avant de le supprimer.","Seleccione un método abreviado de teclado asignado antes de eliminarlo."},
        A{"Removed keyboard shortcut: %1.","Tastenkombination entfernt: %1.","Сочетание удалено: %1.","Сполучення видалено: %1.","Raccourci clavier supprimé : %1.","Método abreviado de teclado eliminado: %1."},
        A{"%1. Assigned keyboard shortcuts: %2","%1. Zugewiesene Tastenkombinationen: %2","%1. Назначенные сочетания: %2","%1. Призначені сполучення: %2","%1. Raccourcis clavier attribués : %2","%1. Métodos abreviados de teclado asignados: %2"},
        A{"Use the arrow keys to select a command. Press Enter to add or edit keyboard shortcuts, Delete to remove assignments, or Tab to move to the buttons.","Wählen Sie mit den Pfeiltasten einen Befehl. Eingabe fügt Tastenkombinationen hinzu oder bearbeitet sie, Entf entfernt Zuweisungen und Tab wechselt zu den Schaltflächen.","Выберите команду стрелками. Enter добавляет или изменяет сочетания, Delete удаляет назначения, Tab переходит к кнопкам.","Виберіть команду стрілками. Enter додає або змінює сполучення, Delete видаляє призначення, Tab переходить до кнопок.","Sélectionnez une commande avec les flèches. Entrée ajoute ou modifie les raccourcis clavier, Suppr retire les attributions et Tab passe aux boutons.","Seleccione un comando con las flechas. Intro añade o edita métodos abreviados de teclado, Supr elimina asignaciones y Tab pasa a los botones."},
        A{"Removed all keyboard shortcuts from %1. Choose Save and Close to save this change.","Alle Tastenkombinationen von %1 wurden entfernt. Wählen Sie Speichern und schließen, um diese Änderung zu speichern.","Все сочетания команды %1 удалены. Выберите «Сохранить и закрыть», чтобы сохранить изменение.","Усі сполучення команди %1 видалено. Виберіть «Зберегти й закрити», щоб зберегти зміну.","Tous les raccourcis clavier de %1 ont été supprimés. Choisissez Enregistrer et fermer pour enregistrer cette modification.","Se eliminaron todos los métodos abreviados de teclado de %1. Elija Guardar y cerrar para guardar el cambio."},
        A{"You have unsaved changes. Save changes?","Sie haben nicht gespeicherte Änderungen. Änderungen speichern?","Есть несохранённые изменения. Сохранить их?","Є незбережені зміни. Зберегти їх?","Vous avez des modifications non enregistrées. Les enregistrer ?","Tiene cambios sin guardar. ¿Desea guardarlos?"},
        A{"Choose Save to apply the changes, Discard to close without saving, or Cancel to return to the editor.","Wählen Sie Speichern, um die Änderungen anzuwenden, Verwerfen, um ohne Speichern zu schließen, oder Abbrechen, um zum Editor zurückzukehren.","Выберите «Сохранить», чтобы применить изменения, «Не сохранять», чтобы закрыть без сохранения, или «Отмена», чтобы вернуться в редактор.","Виберіть «Зберегти», щоб застосувати зміни, «Не зберігати», щоб закрити без збереження, або «Скасувати», щоб повернутися до редактора.","Choisissez Enregistrer pour appliquer les modifications, Ignorer pour fermer sans enregistrer ou Annuler pour revenir à l’éditeur.","Elija Guardar para aplicar los cambios, Descartar para cerrar sin guardar o Cancelar para volver al editor."},
        A{"Keyboard Shortcut Editor","Tastenkombinations-Editor","Редактор сочетаний клавиш","Редактор сполучень клавіш","Éditeur de raccourcis clavier","Editor de métodos abreviados de teclado"},
        A{"&Add or Edit","&Hinzufügen oder bearbeiten","&Добавить или изменить","&Додати або змінити","&Ajouter ou modifier","&Añadir o editar"},
        A{"&Save and Close","&Speichern und schließen","&Сохранить и закрыть","&Зберегти й закрити","&Enregistrer et fermer","&Guardar y cerrar"},
        A{"&Allow OBS Studio to manage whether keyboard shortcuts work outside OBS","&OBS Studio verwalten lassen, ob Tastenkombinationen außerhalb von OBS funktionieren","Разрешить OBS Studio управлять работой сочетаний &клавиш вне OBS","Дозволити OBS Studio керувати роботою сполучень клавіш &поза OBS","&Autoriser OBS Studio à gérer le fonctionnement des raccourcis clavier hors d’OBS","Permitir que OBS Studio gestione si los métodos abreviados de teclado funcionan &fuera de OBS"},
        A{"The system-wide keyboard shortcut preference could not be saved. The editor will remain open so you can try again.","Die Einstellung für systemweite Tastenkombinationen konnte nicht gespeichert werden. Der Editor bleibt für einen erneuten Versuch geöffnet.","Не удалось сохранить настройку общесистемных сочетаний клавиш. Редактор останется открытым для повторной попытки.","Не вдалося зберегти налаштування загальносистемних сполучень клавіш. Редактор залишиться відкритим для повторної спроби.","La préférence des raccourcis clavier système n’a pas pu être enregistrée. L’éditeur reste ouvert pour réessayer.","No se pudo guardar la preferencia de métodos abreviados de teclado de todo el sistema. El editor permanecerá abierto para volver a intentarlo."},
        A{"One or more keyboard shortcuts are also assigned to other commands.","Eine oder mehrere Tastenkombinationen sind auch anderen Befehlen zugewiesen.","Одно или несколько сочетаний назначены другим командам.","Одне або кілька сполучень призначено іншим командам.","Un ou plusieurs raccourcis clavier sont également attribués à d’autres commandes.","Uno o varios métodos abreviados de teclado también están asignados a otros comandos."},
        A{"%1 is also assigned to %2.","%1 ist auch %2 zugewiesen.","%1 также назначено команде %2.","%1 також призначено команді %2.","%1 est également attribué à %2.","%1 también está asignado a %2."},
        A{"Apply these assignments anyway?","Diese Zuweisungen trotzdem anwenden?","Всё равно применить эти назначения?","Усе одно застосувати ці призначення?","Appliquer quand même ces attributions ?","¿Aplicar estas asignaciones de todos modos?"},
        A{"Apply Anyway","Trotzdem anwenden","Всё равно применить","Усе одно застосувати","Appliquer quand même","Aplicar de todos modos"},
        A{"Return to Editor","Zum Editor zurückkehren","Вернуться в редактор","Повернутися до редактора","Revenir à l’éditeur","Volver al editor"},
        A{"The keyboard shortcut assignments could not be prepared for saving. The previous assignments were restored and the editor will remain open.","Die Tastenkombinationen konnten nicht zum Speichern vorbereitet werden. Die vorherigen Zuweisungen wurden wiederhergestellt und der Editor bleibt geöffnet.","Не удалось подготовить назначения к сохранению. Предыдущие назначения восстановлены, редактор останется открытым.","Не вдалося підготувати призначення до збереження. Попередні призначення відновлено, редактор залишиться відкритим.","Les attributions de raccourcis clavier n’ont pas pu être préparées pour l’enregistrement. Les attributions précédentes ont été restaurées et l’éditeur reste ouvert.","No se pudieron preparar las asignaciones de métodos abreviados de teclado para guardarlas. Se restauraron las asignaciones anteriores y el editor permanecerá abierto."},
        A{"OBS could not save the keyboard shortcut assignments. The previous assignments were restored and the editor will remain open so you can try again.","OBS konnte die Tastenkombinationen nicht speichern. Die vorherigen Zuweisungen wurden wiederhergestellt und der Editor bleibt für einen erneuten Versuch geöffnet.","OBS не удалось сохранить назначения. Предыдущие назначения восстановлены, редактор останется открытым для повторной попытки.","OBS не вдалося зберегти призначення. Попередні призначення відновлено, редактор залишиться відкритим для повторної спроби.","OBS n’a pas pu enregistrer les attributions de raccourcis clavier. Les attributions précédentes ont été restaurées et l’éditeur reste ouvert pour réessayer.","OBS no pudo guardar las asignaciones de métodos abreviados de teclado. Se restauraron las asignaciones anteriores y el editor permanecerá abierto para volver a intentarlo."},
        A{"%1 commands shown.","%1 Befehle angezeigt.","Показано команд: %1.","Показано команд: %1.","%1 commandes affichées.","Se muestran %1 comandos."},
        A{"&Find commands:","Befehle &suchen:","&Найти команды:","&Знайти команди:","&Rechercher des commandes :","&Buscar comandos:"},
        A{"Commands","Befehle","Команды","Команди","Commandes","Comandos"},
        A{"Command","Befehl","Команда","Команда","Commande","Comando"},
        A{"Status","Status","Состояние","Стан","État","Estado"},
        A{"OpenAI &API Settings","OpenAI-&API-Einstellungen","Настройки &API OpenAI","Налаштування &API OpenAI","Paramètres &API OpenAI","Configuración de &API de OpenAI"},
        A{"Accessible Studio - Select Source","Accessible Studio - Quelle auswählen","Accessible Studio - Выбор источника","Accessible Studio - Вибір джерела","Accessible Studio - Sélectionner une source","Accessible Studio - Seleccionar fuente"},
        A{"Source:","Quelle:","Источник:","Джерело:","Source :","Fuente:"},
        A{"No source is available or selected.","Es ist keine Quelle verfügbar oder ausgewählt.","Нет доступного или выбранного источника.","Немає доступного або вибраного джерела.","Aucune source n’est disponible ou sélectionnée.","No hay ninguna fuente disponible o seleccionada."},
        A{"Suggested Actions","Vorgeschlagene Aktionen","Предлагаемые действия","Запропоновані дії","Actions suggérées","Acciones sugeridas"},
        A{"Low","Niedrig","Низкий","Низький","Faible","Bajo"},A{"Medium","Mittel","Средний","Середній","Moyen","Medio"},
        A{"%1. Risk: %2","%1. Risiko: %2","%1. Риск: %2","%1. Ризик: %2","%1. Risque : %2","%1. Riesgo: %2"},
        A{"Unavailable for the current selection, possibly because the source is locked.","Für die aktuelle Auswahl nicht verfügbar, möglicherweise weil die Quelle gesperrt ist.","Недоступно для текущего выбора, возможно, источник заблокирован.","Недоступно для поточного вибору, можливо, джерело заблоковано.","Indisponible pour la sélection actuelle, peut-être parce que la source est verrouillée.","No disponible para la selección actual, posiblemente porque la fuente está bloqueada."},
        A{"Select one action and activate Apply Fix. OBS records the applied transform in its Undo history.","Wählen Sie eine Aktion aus und wählen Sie Korrektur anwenden. OBS zeichnet die angewendete Transformation im Rückgängig-Verlauf auf.","Выберите одно действие и нажмите «Применить исправление». OBS записывает применённое преобразование в историю отмены.","Виберіть одну дію та натисніть «Застосувати виправлення». OBS записує застосоване перетворення в історію скасування.","Sélectionnez une action et activez Appliquer la correction. OBS enregistre la transformation appliquée dans l’historique d’annulation.","Seleccione una acción y active Aplicar corrección. OBS registra la transformación aplicada en el historial de deshacer."},
        A{"Apply Fix","Korrektur anwenden","Применить исправление","Застосувати виправлення","Appliquer la correction","Aplicar corrección"},
        A{"Explain","Erklären","Объяснить","Пояснити","Expliquer","Explicar"},
        A{"Centering changes position only. Fit to canvas changes position and scale while preserving proportions. Reset Transform restores the source's default transform. Flip and Rotate change orientation. Locked or unavailable actions cannot be selected.","Zentrieren ändert nur die Position. An Canvas anpassen ändert Position und Skalierung unter Beibehaltung der Proportionen. Transformation zurücksetzen stellt die Standardtransformation der Quelle wieder her. Spiegeln und Drehen ändern die Ausrichtung. Gesperrte oder nicht verfügbare Aktionen können nicht ausgewählt werden.","Центрирование меняет только положение. Вписывание в холст меняет положение и масштаб с сохранением пропорций. Сброс преобразования восстанавливает исходное преобразование источника. Отражение и поворот меняют ориентацию. Заблокированные и недоступные действия выбрать нельзя.","Центрування змінює лише положення. Вписування в полотно змінює положення й масштаб зі збереженням пропорцій. Скидання перетворення відновлює початкове перетворення джерела. Віддзеркалення й обертання змінюють орієнтацію. Заблоковані та недоступні дії вибрати не можна.","Le centrage ne modifie que la position. Ajuster au canevas modifie la position et l’échelle en conservant les proportions. Réinitialiser la transformation restaure la transformation par défaut de la source. Retourner et Faire pivoter changent l’orientation. Les actions verrouillées ou indisponibles ne peuvent pas être sélectionnées.","Centrar solo cambia la posición. Ajustar al lienzo cambia la posición y la escala conservando las proporciones. Restablecer transformación restaura la transformación predeterminada de la fuente. Voltear y Girar cambian la orientación. No se pueden seleccionar acciones bloqueadas o no disponibles."},
        A{"No actions were applied.","Es wurden keine Aktionen angewendet.","Действия не применялись.","Дії не застосовано.","Aucune action n’a été appliquée.","No se aplicó ninguna acción."},
        A{"Applied:\n%1","Angewendet:\n%1","Применено:\n%1","Застосовано:\n%1","Appliqué :\n%1","Aplicado:\n%1"},
        A{"Use Ctrl+Z in OBS to undo.","Verwenden Sie Strg+Z in OBS zum Rückgängigmachen.","Для отмены нажмите Ctrl+Z в OBS.","Для скасування натисніть Ctrl+Z в OBS.","Utilisez Ctrl+Z dans OBS pour annuler.","Use Ctrl+Z en OBS para deshacer."},
        A{"Skipped because the source state changed or the action became unavailable:\n%1","Übersprungen, weil sich der Quellenstatus geändert hat oder die Aktion nicht mehr verfügbar war:\n%1","Пропущено, поскольку состояние источника изменилось или действие стало недоступно:\n%1","Пропущено, оскільки стан джерела змінився або дія стала недоступною:\n%1","Ignoré parce que l’état de la source a changé ou que l’action est devenue indisponible :\n%1","Omitido porque cambió el estado de la fuente o la acción dejó de estar disponible:\n%1"},
        A{"Center fully","Vollständig zentrieren","Центрировать полностью","Центрувати повністю","Centrer complètement","Centrar por completo"},A{"Center horizontally","Horizontal zentrieren","Центрировать по горизонтали","Центрувати горизонтально","Centrer horizontalement","Centrar horizontalmente"},A{"Center vertically","Vertikal zentrieren","Центрировать по вертикали","Центрувати вертикально","Centrer verticalement","Centrar verticalmente"},
        A{"Fit to canvas, preserving proportions","An Canvas anpassen, Proportionen beibehalten","Вписать в холст с сохранением пропорций","Вписати в полотно зі збереженням пропорцій","Ajuster au canevas en conservant les proportions","Ajustar al lienzo conservando las proporciones"},A{"Reset transform","Transformation zurücksetzen","Сбросить преобразование","Скинути перетворення","Réinitialiser la transformation","Restablecer transformación"},A{"Flip horizontally","Horizontal spiegeln","Отразить по горизонтали","Віддзеркалити горизонтально","Retourner horizontalement","Voltear horizontalmente"},A{"Flip vertically","Vertikal spiegeln","Отразить по вертикали","Віддзеркалити вертикально","Retourner verticalement","Voltear verticalmente"},A{"Rotate 90 degrees clockwise","Um 90 Grad im Uhrzeigersinn drehen","Повернуть на 90 градусов по часовой стрелке","Обернути на 90 градусів за годинниковою стрілкою","Faire pivoter de 90 degrés dans le sens horaire","Girar 90 grados en sentido horario"},A{"Rotate 90 degrees counterclockwise","Um 90 Grad gegen den Uhrzeigersinn drehen","Повернуть на 90 градусов против часовой стрелки","Обернути на 90 градусів проти годинникової стрілки","Faire pivoter de 90 degrés dans le sens antihoraire","Girar 90 grados en sentido antihorario"},A{"Rotate 180 degrees","Um 180 Grad drehen","Повернуть на 180 градусов","Обернути на 180 градусів","Faire pivoter de 180 degrés","Girar 180 grados"},
        A{"Analyzing compatibility with OpenAI. This may take several minutes.","Kompatibilität wird mit OpenAI analysiert. Dies kann mehrere Minuten dauern.","Анализ совместимости с помощью OpenAI. Это может занять несколько минут.","Аналіз сумісності за допомогою OpenAI. Це може тривати кілька хвилин.","Analyse de la compatibilité avec OpenAI. Cela peut prendre plusieurs minutes.","Analizando la compatibilidad con OpenAI. Puede tardar varios minutos."},
        A{"Compatibility analysis in progress","Kompatibilitätsanalyse läuft","Выполняется анализ совместимости","Триває аналіз сумісності","Analyse de compatibilité en cours","Análisis de compatibilidad en curso"},
        A{"This function requires an OpenAI API key. Open Tools > Accessible Studio > Video Tools > Manage OpenAI API Keys, save a key, and run the compatibility analysis again. All non-OpenAI plugin functions remain available without a key.","Diese Funktion benötigt einen OpenAI-API-Schlüssel. Öffnen Sie Werkzeuge > Accessible Studio > Videowerkzeuge > OpenAI-API-Schlüssel verwalten, speichern Sie einen Schlüssel und führen Sie die Kompatibilitätsanalyse erneut aus. Alle Funktionen ohne OpenAI bleiben ohne Schlüssel verfügbar.","Для этой функции нужен ключ API OpenAI. Откройте Сервис > Accessible Studio > Видеоинструменты > Управление ключами API OpenAI, сохраните ключ и повторите анализ совместимости. Все функции, не связанные с OpenAI, доступны без ключа.","Для цієї функції потрібен ключ API OpenAI. Відкрийте Сервіс > Accessible Studio > Відеоінструменти > Керування ключами API OpenAI, збережіть ключ і повторіть аналіз сумісності. Усі функції, не пов’язані з OpenAI, доступні без ключа.","Cette fonction nécessite une clé API OpenAI. Ouvrez Outils > Accessible Studio > Outils vidéo > Gérer les clés API OpenAI, enregistrez une clé, puis relancez l’analyse de compatibilité. Toutes les fonctions sans OpenAI restent disponibles sans clé.","Esta función requiere una clave de API de OpenAI. Abra Herramientas > Accessible Studio > Herramientas de vídeo > Administrar claves de API de OpenAI, guarde una clave y vuelva a ejecutar el análisis de compatibilidad. Todas las funciones ajenas a OpenAI siguen disponibles sin clave."},
        A{"The report was displayed, but it could not be saved. Running the analysis again may contact OpenAI and incur another API charge.","Der Bericht wurde angezeigt, konnte aber nicht gespeichert werden. Eine erneute Analyse kann OpenAI kontaktieren und weitere API-Kosten verursachen.","Отчёт показан, но его не удалось сохранить. Повторный анализ может снова обратиться к OpenAI и вызвать дополнительные расходы API.","Звіт показано, але його не вдалося зберегти. Повторний аналіз може знову звернутися до OpenAI та спричинити додаткові витрати API.","Le rapport a été affiché, mais n’a pas pu être enregistré. Une nouvelle analyse peut contacter OpenAI et entraîner de nouveaux frais d’API.","El informe se mostró, pero no se pudo guardar. Volver a ejecutar el análisis puede contactar con OpenAI y generar otro cargo de API."},
        A{"Accessible Studio Compatibility Analysis","Accessible Studio Kompatibilitätsanalyse","Анализ совместимости Accessible Studio","Аналіз сумісності Accessible Studio","Analyse de compatibilité d’Accessible Studio","Análisis de compatibilidad de Accessible Studio"},
        A{"Accessible Studio has not been tested with OBS Studio %1.","Accessible Studio wurde nicht mit OBS Studio %1 getestet.","Accessible Studio не тестировалась с OBS Studio %1.","Accessible Studio не тестувалася з OBS Studio %1.","Accessible Studio n’a pas été testé avec OBS Studio %1.","Accessible Studio no se ha probado con OBS Studio %1."},
        A{"Continuing may cause missing features, instability, or crashes. Analyze Compatibility uses your OpenAI API key, may incur an API charge, and reuses a saved report for this OBS and plugin version.","Das Fortfahren kann zu fehlenden Funktionen, Instabilität oder Abstürzen führen. Kompatibilität analysieren verwendet Ihren OpenAI-API-Schlüssel, kann API-Kosten verursachen und nutzt einen gespeicherten Bericht für diese OBS- und Plugin-Version erneut.","Продолжение может привести к отсутствию функций, нестабильности или сбоям. Анализ совместимости использует ваш ключ API OpenAI, может повлечь расходы и повторно использует сохранённый отчёт для этой версии OBS и плагина.","Продовження може призвести до відсутності функцій, нестабільності або збоїв. Аналіз сумісності використовує ваш ключ API OpenAI, може спричинити витрати й повторно використовує збережений звіт для цієї версії OBS і плагіна.","Continuer peut entraîner des fonctions manquantes, une instabilité ou des plantages. Analyser la compatibilité utilise votre clé API OpenAI, peut entraîner des frais et réutilise un rapport enregistré pour cette version d’OBS et du module.","Continuar puede provocar funciones ausentes, inestabilidad o bloqueos. Analizar compatibilidad usa su clave de API de OpenAI, puede generar un cargo y reutiliza un informe guardado para esta versión de OBS y del complemento."},
        A{"Run Anyway","Trotzdem ausführen","Запустить всё равно","Усе одно запустити","Exécuter quand même","Ejecutar de todos modos"},
        A{"Analyze Compatibility","Kompatibilität analysieren","Анализировать совместимость","Аналізувати сумісність","Analyser la compatibilité","Analizar compatibilidad"},
        A{"Cancel","Abbrechen","Отмена","Скасувати","Annuler","Cancelar"},
        A{"Play or pause media","Medienwiedergabe starten oder pausieren","Воспроизвести или приостановить медиа","Відтворити або призупинити медіа","Lire ou mettre le média en pause","Reproducir o pausar contenido multimedia"},
        A{"Stop media","Medienwiedergabe stoppen","Остановить медиа","Зупинити медіа","Arrêter le média","Detener contenido multimedia"},
        A{"Previous media","Vorheriges Medium","Предыдущее медиа","Попереднє медіа","Média précédent","Contenido multimedia anterior"},
        A{"Next media","Nächstes Medium","Следующее медиа","Наступне медіа","Média suivant","Contenido multimedia siguiente"},
        A{"Media position","Wiedergabeposition","Позиция воспроизведения","Позиція відтворення","Position du média","Posición de reproducción"},
        A{".Focus Media Controls",".Mediensteuerung fokussieren",".Перейти к элементам управления мультимедиа",".Перейти до елементів керування медіа",".Placer le focus sur les commandes multimédias",".Enfocar los controles multimedia"},
        A{".Open Accessible Studio menu",".Menü von Accessible Studio öffnen",".Открыть меню Accessible Studio",".Відкрити меню Accessible Studio",".Ouvrir le menu Accessible Studio",".Abrir el menú de Accessible Studio"},
        A{"This command has no keyboard shortcuts to remove.","Dieser Befehl hat keine zu entfernenden Tastenkombinationen.","У этой команды нет сочетаний для удаления.","Ця команда не має сполучень для видалення.","Cette commande n’a aucun raccourci clavier à supprimer.","Este comando no tiene métodos abreviados de teclado que eliminar."},
        A{"Save","Speichern","Сохранить","Зберегти","Enregistrer","Guardar"},
        A{"Discard","Verwerfen","Не сохранять","Не зберігати","Ignorer","Descartar"},
        A{"OK","OK","OK","OK","OK","Aceptar"},
        A{"Audio source","Audioquelle","Аудиоисточник","Аудіоджерело","Source audio","Fuente de audio"},
        A{"OBS Studio","OBS Studio","OBS Studio","OBS Studio","OBS Studio","OBS Studio"},
        A{"Plugin","Plugin","Плагин","Плагін","Module","Complemento"},
        A{"Yes","Ja","Да","Так","Oui","Sí"},
        A{"No","Nein","Нет","Ні","Non","No"},
        A{"Fit to canvas was applied. Checking the fitted image quality.","An Canvas anpassen wurde angewendet. Die Bildqualität des angepassten Bildes wird geprüft.","Вписывание в холст применено. Проверяется качество вписанного изображения.","Вписування в полотно застосовано. Перевіряється якість вписаного зображення.","L’ajustement au canevas a été appliqué. Vérification de la qualité de l’image ajustée.","Se aplicó Ajustar al lienzo. Comprobando la calidad de la imagen ajustada."},
        A{"Fit to canvas was applied. No unacceptable blur, grain, noise, or pixelation was detected.","An Canvas anpassen wurde angewendet. Es wurde keine unzumutbare Unschärfe, Körnung, kein Rauschen und keine Pixelbildung erkannt.","Вписывание в холст применено. Недопустимого размытия, зернистости, шума или пикселизации не обнаружено.","Вписування в полотно застосовано. Неприйнятного розмиття, зернистості, шуму або пікселізації не виявлено.","L’ajustement au canevas a été appliqué. Aucun flou, grain, bruit ou pixellisation inacceptable n’a été détecté.","Se aplicó Ajustar al lienzo. No se detectó desenfoque, grano, ruido ni pixelación inaceptables."},
        A{"Fit to canvas was undone because the fitted image was unusably blurred or grainy, or its quality could not be confirmed. Center fully was applied instead.","An Canvas anpassen wurde rückgängig gemacht, weil das angepasste Bild unbrauchbar unscharf oder körnig war oder seine Qualität nicht bestätigt werden konnte. Stattdessen wurde Vollständig zentrieren angewendet.","Вписывание в холст отменено, поскольку вписанное изображение оказалось неприемлемо размытым или зернистым либо его качество не удалось подтвердить. Вместо этого применено полное центрирование.","Вписування в полотно скасовано, оскільки вписане зображення було неприйнятно розмитим або зернистим чи його якість не вдалося підтвердити. Натомість застосовано повне центрування.","L’ajustement au canevas a été annulé parce que l’image ajustée était floue ou granuleuse au point d’être inutilisable, ou parce que sa qualité n’a pas pu être confirmée. Le centrage complet a été appliqué à la place.","Se deshizo Ajustar al lienzo porque la imagen ajustada estaba desenfocada o granulada hasta resultar inutilizable, o porque no se pudo confirmar su calidad. Se aplicó Centrar por completo en su lugar."},
        A{"The fitted image quality could not be confirmed, but Fit to canvas could not be undone automatically. Use Ctrl+Z in OBS to restore the previous transform.","Die Qualität des angepassten Bildes konnte nicht bestätigt werden, aber An Canvas anpassen konnte nicht automatisch rückgängig gemacht werden. Verwenden Sie Strg+Z in OBS, um die vorherige Transformation wiederherzustellen.","Качество вписанного изображения не удалось подтвердить, но вписывание в холст нельзя было отменить автоматически. Нажмите Ctrl+Z в OBS, чтобы восстановить предыдущее преобразование.","Якість вписаного зображення не вдалося підтвердити, але вписування в полотно не вдалося скасувати автоматично. Натисніть Ctrl+Z в OBS, щоб відновити попереднє перетворення.","La qualité de l’image ajustée n’a pas pu être confirmée, mais l’ajustement au canevas n’a pas pu être annulé automatiquement. Utilisez Ctrl+Z dans OBS pour restaurer la transformation précédente.","No se pudo confirmar la calidad de la imagen ajustada, pero Ajustar al lienzo no se pudo deshacer automáticamente. Use Ctrl+Z en OBS para restaurar la transformación anterior."},
        A{"Fit to canvas was undone, but Center fully could not be applied because the source state changed or the action became unavailable.","An Canvas anpassen wurde rückgängig gemacht, aber Vollständig zentrieren konnte nicht angewendet werden, weil sich der Quellenstatus geändert hat oder die Aktion nicht mehr verfügbar war.","Вписывание в холст отменено, но полное центрирование применить не удалось, поскольку состояние источника изменилось или действие стало недоступно.","Вписування в полотно скасовано, але повне центрування не вдалося застосувати, оскільки стан джерела змінився або дія стала недоступною.","L’ajustement au canevas a été annulé, mais le centrage complet n’a pas pu être appliqué parce que l’état de la source a changé ou que l’action est devenue indisponible.","Se deshizo Ajustar al lienzo, pero no se pudo aplicar Centrar por completo porque cambió el estado de la fuente o la acción dejó de estar disponible."},
        A{"Audible Meter Settings…","Audible-Meter-Einstellungen…","Настройки звукового индикатора…","Налаштування звукового індикатора…","Paramètres d’Audible Meter…","Configuración de Audible Meter…"},
        A{"Output warning level","Warnpegel für die Ausgabe","Уровень предупреждения выхода","Рівень попередження виходу","Niveau d’avertissement de sortie","Nivel de aviso de salida"},
        A{"The output level at which the warning timer begins. This does not change the green, yellow, and red measurements.","Der Ausgangspegel, bei dem der Warntimer beginnt. Dies ändert die Messungen für Grün, Gelb und Rot nicht.","Уровень выхода, при котором запускается таймер предупреждения. Это не изменяет измерения зелёной, жёлтой и красной зон.","Рівень виходу, за якого запускається таймер попередження. Це не змінює вимірювання зеленої, жовтої та червоної зон.","Niveau de sortie auquel démarre le délai d’avertissement. Cela ne modifie pas les mesures verte, jaune et rouge.","Nivel de salida en el que comienza el temporizador del aviso. Esto no cambia las mediciones verde, amarilla y roja."},
        A{"Time above warning level","Zeit über dem Warnpegel","Время выше уровня предупреждения","Час вище рівня попередження","Durée au-dessus du niveau d’avertissement","Tiempo por encima del nivel de aviso"},
        A{"How long the output must remain above the warning level before a warning starts.","Wie lange die Ausgabe über dem Warnpegel bleiben muss, bevor eine Warnung beginnt.","Как долго выход должен оставаться выше уровня предупреждения до начала предупреждения.","Як довго вихід має залишатися вище рівня попередження до початку попередження.","Durée pendant laquelle la sortie doit rester au-dessus du niveau d’avertissement avant le déclenchement d’un avertissement.","Tiempo que la salida debe permanecer por encima del nivel de aviso antes de que comience un aviso."},
        A{"Peak safety margin","Spitzen-Sicherheitsabstand","Запас до пикового уровня","Запас до пікового рівня","Marge de sécurité des crêtes","Margen de seguridad de picos"},
        A{"Automatic adjustment places the observed peak this far below the warning level. A smaller margin keeps the source louder.","Die automatische Anpassung setzt die beobachtete Spitze um diesen Wert unter den Warnpegel. Ein kleinerer Abstand lässt die Quelle lauter.","Автоматическая регулировка помещает наблюдавшийся пик на это расстояние ниже уровня предупреждения. Меньший запас сохраняет источник громче.","Автоматичне регулювання розміщує спостережуваний пік на цю величину нижче рівня попередження. Менший запас зберігає джерело гучнішим.","Le réglage automatique place la crête observée à cette distance sous le niveau d’avertissement. Une marge plus faible conserve un niveau plus élevé.","El ajuste automático sitúa el pico observado a esta distancia por debajo del nivel de aviso. Un margen menor mantiene la fuente más alta."},
        A{"Maximum automatic reduction","Maximale automatische Absenkung","Максимальное автоматическое снижение","Максимальне автоматичне зниження","Réduction automatique maximale","Reducción automática máxima"},
        A{"The greatest amount by which one automatic adjustment may lower a source.","Der größte Wert, um den eine automatische Anpassung eine Quelle absenken darf.","Наибольшая величина, на которую одна автоматическая регулировка может понизить источник.","Найбільша величина, на яку одне автоматичне регулювання може знизити джерело.","Réduction maximale qu’un réglage automatique peut appliquer à une source.","La cantidad máxima que un ajuste automático puede reducir una fuente."},
        A{"Pre-fader stop list","Stoppliste für Pegel vor dem Regler","Стоп-лист проверки до регулятора","Стоп-лист перевірки до регулятора","Liste d’arrêt avant curseur","Lista de exclusión anterior al control"},
        A{"Sources for which Audible Meter will not report pre-fader level problems. Select a source and press Delete or activate Remove to check it again.","Quellen, für die Audible Meter keine Pegelprobleme vor dem Regler meldet. Wählen Sie eine Quelle aus und drücken Sie Entf oder aktivieren Sie Entfernen, um sie wieder zu prüfen.","Источники, для которых Audible Meter не сообщает о проблемах уровня до регулятора. Выберите источник и нажмите Delete или кнопку «Удалить», чтобы снова проверять его.","Джерела, для яких Audible Meter не повідомляє про проблеми рівня до регулятора. Виберіть джерело й натисніть Delete або кнопку «Вилучити», щоб знову перевіряти його.","Sources pour lesquelles Audible Meter ne signale pas les problèmes de niveau avant curseur. Sélectionnez une source et appuyez sur Suppr ou activez Retirer pour la vérifier à nouveau.","Fuentes para las que Audible Meter no informa de problemas de nivel anterior al control. Seleccione una fuente y pulse Supr o active Quitar para volver a comprobarla."},
        A{"No sources are on the pre-fader stop list.","Keine Quellen befinden sich auf der Stoppliste für Pegel vor dem Regler.","В стоп-листе проверки до регулятора нет источников.","У стоп-листі перевірки до регулятора немає джерел.","Aucune source ne figure dans la liste d’arrêt avant curseur.","No hay fuentes en la lista de exclusión anterior al control."},
        A{"Remove","Entfernen","Удалить","Вилучити","Retirer","Quitar"},
        A{"The pre-fader stop list could not be saved.","Die Stoppliste für Pegel vor dem Regler konnte nicht gespeichert werden.","Не удалось сохранить стоп-лист проверки до регулятора.","Не вдалося зберегти стоп-лист перевірки до регулятора.","La liste d’arrêt avant curseur n’a pas pu être enregistrée.","No se pudo guardar la lista de exclusión anterior al control."},
        A{"Restore Defaults","Standardeinstellungen wiederherstellen","Восстановить значения по умолчанию","Відновити типові значення","Rétablir les valeurs par défaut","Restaurar valores predeterminados"},
        A{"Audible Meter settings will be restored to default. All your personalized settings for this feature will be lost. Do you want to proceed?","Die Audible-Meter-Einstellungen werden auf die Standardwerte zurückgesetzt. Alle Ihre persönlichen Einstellungen für diese Funktion gehen verloren. Möchten Sie fortfahren?","Настройки Audible Meter будут восстановлены до значений по умолчанию. Все ваши персональные настройки этой функции будут потеряны. Продолжить?","Налаштування Audible Meter буде відновлено до типових значень. Усі ваші персоналізовані налаштування цієї функції буде втрачено. Продовжити?","Les paramètres d’Audible Meter seront rétablis à leurs valeurs par défaut. Tous vos paramètres personnalisés pour cette fonctionnalité seront perdus. Voulez-vous continuer ?","La configuración de Audible Meter se restaurará a los valores predeterminados. Se perderá toda su configuración personalizada para esta función. ¿Desea continuar?"},
        A{"Sound Doctor settings will be restored to default. All your personalized settings for this feature will be lost. Do you want to proceed?","Die Sound-Doctor-Einstellungen werden auf die Standardwerte zurückgesetzt. Alle Ihre persönlichen Einstellungen für diese Funktion gehen verloren. Möchten Sie fortfahren?","Настройки Sound Doctor будут восстановлены до значений по умолчанию. Все ваши персональные настройки этой функции будут потеряны. Продолжить?","Налаштування Sound Doctor буде відновлено до типових значень. Усі ваші персоналізовані налаштування цієї функції буде втрачено. Продовжити?","Les paramètres de Sound Doctor seront rétablis à leurs valeurs par défaut. Tous vos paramètres personnalisés pour cette fonctionnalité seront perdus. Voulez-vous continuer ?","La configuración de Sound Doctor se restaurará a los valores predeterminados. Se perderá toda su configuración personalizada para esta función. ¿Desea continuar?"},
        A{"The Audible Meter settings could not be saved.","Die Audible-Meter-Einstellungen konnten nicht gespeichert werden.","Не удалось сохранить настройки звукового индикатора.","Не вдалося зберегти налаштування звукового індикатора.","Les paramètres d’Audible Meter n’ont pas pu être enregistrés.","No se pudo guardar la configuración de Audible Meter."},
        A{"Minimum dynamic variation for compression","Minimale Dynamikvariation für Kompression","Минимальный динамический разброс для компрессии","Мінімальний динамічний розкид для компресії","Variation dynamique minimale pour la compression","Variación dinámica mínima para la compresión"},
        A{"The minimum difference between typical and louder passages required for a compressor recommendation. Lower values produce more recommendations.","Der Mindestunterschied zwischen typischen und lauteren Passagen für eine Kompressorempfehlung. Niedrigere Werte erzeugen mehr Empfehlungen.","Минимальная разница между типичными и более громкими фрагментами для рекомендации компрессора. Меньшие значения дают больше рекомендаций.","Мінімальна різниця між типовими й гучнішими фрагментами для рекомендації компресора. Менші значення дають більше рекомендацій.","Différence minimale entre les passages typiques et plus forts requise pour recommander un compresseur. Des valeurs plus faibles produisent davantage de recommandations.","Diferencia mínima entre los pasajes habituales y los más fuertes necesaria para recomendar un compresor. Los valores menores producen más recomendaciones."},
        A{"Maximum recommended compressor ratio","Rapport maximal de compresseur recommandé","Максимальное рекомендуемое соотношение компрессора","Максимальне рекомендоване співвідношення компресора","Rapport maximal de compresseur recommandé","Relación máxima recomendada del compresor"},
        A{"The strongest ratio Sound Doctor may recommend. Its adaptive calculation can still choose a gentler ratio.","Das stärkste Verhältnis, das Sound Doctor empfehlen darf. Die adaptive Berechnung kann weiterhin ein sanfteres Verhältnis wählen.","Наибольшее соотношение, которое может рекомендовать Sound Doctor. Адаптивный расчёт всё равно может выбрать более мягкое значение.","Найбільше співвідношення, яке може рекомендувати Sound Doctor. Адаптивний розрахунок усе одно може вибрати м’якше значення.","Rapport le plus fort que Sound Doctor peut recommander. Son calcul adaptatif peut toujours choisir un rapport plus doux.","La relación más fuerte que puede recomendar Sound Doctor. El cálculo adaptativo aún puede elegir una relación más suave."},
        A{"Sources eligible for limiter recommendations","Für Limiter-Empfehlungen geeignete Quellen","Источники для рекомендаций лимитера","Джерела для рекомендацій лімітера","Sources admissibles aux recommandations de limiteur","Fuentes aptas para recomendaciones de limitador"},
        A{"Choose whether preventive limiter recommendations apply only to likely live inputs or to every sufficiently active audio source.","Wählen Sie, ob vorbeugende Limiter-Empfehlungen nur für wahrscheinliche Live-Eingänge oder für jede ausreichend aktive Audioquelle gelten.","Выберите, применять ли профилактические рекомендации лимитера только к вероятным живым входам или ко всем достаточно активным аудиоисточникам.","Виберіть, чи застосовувати профілактичні рекомендації лімітера лише до ймовірних живих входів або до всіх достатньо активних аудіоджерел.","Choisissez si les recommandations préventives de limiteur s’appliquent uniquement aux entrées probablement en direct ou à toute source audio suffisamment active.","Elija si las recomendaciones preventivas de limitador se aplican solo a probables entradas en directo o a todas las fuentes de audio suficientemente activas."},
        A{"Likely live inputs only","Nur wahrscheinliche Live-Eingänge","Только вероятные живые входы","Лише ймовірні живі входи","Entrées probablement en direct uniquement","Solo probables entradas en directo"},
        A{"All active audio sources","Alle aktiven Audioquellen","Все активные аудиоисточники","Усі активні аудіоджерела","Toutes les sources audio actives","Todas las fuentes de audio activas"},
        A{"Recommended limiter ceiling","Empfohlener Limiter-Grenzwert","Рекомендуемый предел лимитера","Рекомендована межа лімітера","Plafond de limiteur recommandé","Límite recomendado del limitador"},
        A{"The output ceiling used when Sound Doctor recommends and creates a limiter.","Der Ausgangsgrenzwert, den Sound Doctor beim Empfehlen und Erstellen eines Limiters verwendet.","Выходной предел, который Sound Doctor использует при рекомендации и создании лимитера.","Вихідна межа, яку Sound Doctor використовує під час рекомендації та створення лімітера.","Plafond de sortie utilisé lorsque Sound Doctor recommande et crée un limiteur.","El límite de salida que Sound Doctor utiliza al recomendar y crear un limitador."},
        A{"The Sound Doctor settings could not be saved.","Die Sound-Doctor-Einstellungen konnten nicht gespeichert werden.","Не удалось сохранить настройки Sound Doctor.","Не вдалося зберегти налаштування Sound Doctor.","Les paramètres de Sound Doctor n’ont pas pu être enregistrés.","No se pudo guardar la configuración de Sound Doctor."},
        A{"Audio Tools","Audiowerkzeuge","Аудиоинструменты","Аудіоінструменти","Outils audio","Herramientas de audio"},
        A{"Video Tools","Videowerkzeuge","Видеоинструменты","Відеоінструменти","Outils vidéo","Herramientas de vídeo"},
        A{"Accessible Volume Console","Barrierefreie Lautstärkekonsole","Доступная консоль громкости","Доступна консоль гучності","Console de volume accessible","Consola de volumen accesible"},
        A{"Audible Meter","Audible Meter","Звуковой индикатор","Звуковий індикатор","Audible Meter","Audible Meter"},
        A{"Sound Doctor","Sound Doctor","Консультант по звуку","Консультант зі звуку","Sound Doctor","Sound Doctor"},
        A{"Advanced Sound Settings…","Erweiterte Audioeinstellungen…","Расширенные настройки звука…","Розширені налаштування звуку…","Paramètres audio avancés…","Configuración avanzada de sonido…"},
        A{"Short Canvas Description","Kurze Canvas-Beschreibung","Краткое описание холста","Короткий опис полотна","Description courte du canevas","Descripción breve del lienzo"},
        A{"Manage OpenAI API Keys…","OpenAI-API-Schlüssel verwalten…","Управление ключами API OpenAI…","Керування ключами API OpenAI…","Gérer les clés API OpenAI…","Administrar claves de API de OpenAI…"},
        A{"Open User Manual","Benutzerhandbuch öffnen","Открыть руководство пользователя","Відкрити посібник користувача","Ouvrir le manuel d’utilisation","Abrir el manual del usuario"},
        A{"Accessible Studio could not open the user manual. Verify that the localized HTML manuals are installed and that Windows has a default web browser.","Accessible Studio konnte das Benutzerhandbuch nicht öffnen. Prüfen Sie, ob die lokalisierten HTML-Handbücher installiert sind und ob unter Windows ein Standardbrowser eingerichtet ist.","Accessible Studio не удалось открыть руководство пользователя. Убедитесь, что локализованные руководства HTML установлены и в Windows настроен браузер по умолчанию.","Accessible Studio не вдалося відкрити посібник користувача. Переконайтеся, що локалізовані посібники HTML встановлено й у Windows налаштовано типовий браузер.","Accessible Studio n’a pas pu ouvrir le manuel d’utilisation. Vérifiez que les manuels HTML localisés sont installés et qu’un navigateur par défaut est configuré dans Windows.","Accessible Studio no pudo abrir el manual del usuario. Compruebe que los manuales HTML localizados estén instalados y que Windows tenga configurado un navegador predeterminado."}
    };static_assert(std::size(text)==static_cast<size_t>(LocalText::Count));return QString::fromUtf8(text[static_cast<size_t>(id)][LanguageIndex()]);
}

static std::wstring LWide(LocalText id){return LText(id).toStdWString();}

static QString LAccessibleLabel(LocalText id){
    QString text=LText(id).remove(u'&').trimmed();
    if(text.endsWith(u':'))text.chop(1);
    return text.trimmed();
}
